(function(global){
'use strict';
const VERSION='10.5.4-beta.55-restaurant-closure.1';
const PAGES=new Set(['foodIngredients','foodRecipes','foodOperations','suppliers','purchasing','stockCount','transfers','tables']);
const TITLE={foodIngredients:'الخامات',foodRecipes:'الوصفات وFood Cost',foodOperations:'الإنتاج والهالك',suppliers:'الموردين',purchasing:'مشتريات الخامات',stockCount:'جرد الخامات',transfers:'تحويلات الخامات',tables:'الصالات والترابيزات'};
const FEATURE={foodIngredients:'food.ingredients',foodRecipes:'food.recipes'};
const FOOD_OP_FEATURES=['food.prep','food.production','food.waste','food.costing'];
let wired=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmt=n=>Number(n||0).toFixed(3),money=n=>Number(n||0).toFixed(2);
const toast=m=>{try{return global.toast?.(m)}catch{};console.warn(m)};
const rest=(t,q='',o={})=>global.rest(t,q,o);
const rpc=(n,p={})=>global.rpc(n,p);
const tx=()=>global.crypto?.randomUUID?.()||`restaurant-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const branch=()=>Number(global.currentBranchId?.()||0);
function cfg(){try{return JSON.parse(localStorage.getItem('sharawlaRuntimeConfigV1')||'{}')||{}}catch{return {}}}
function profile(){return String(cfg().pos_profile||'').trim().toLowerCase()}
function isRestaurant(){return profile()==='restaurant'}
function enabledFeatures(){return new Set((Array.isArray(cfg().enabled_features)?cfg().enabled_features:[]).map(x=>String(x||'').trim().toLowerCase()))}
function hasFeature(code){return enabledFeatures().has(String(code).toLowerCase())}
function pageFeatureOn(page){if(FEATURE[page])return hasFeature(FEATURE[page]);if(page==='foodOperations')return FOOD_OP_FEATURES.some(hasFeature);return true}
function pageAllowed(page){try{return global.canAccessPage?.(page)!==false}catch{return true}}
function moduleOn(code){try{return global.moduleEnabled?.(code)!==false}catch{return true}}
function canPage(page){if(!isRestaurant()||!pageFeatureOn(page))return false;if(page==='tables'&&!moduleOn('tables'))return false;if(['suppliers','purchasing','stockCount','transfers','foodIngredients','foodRecipes','foodOperations'].includes(page)&&!moduleOn('inventory'))return false;return pageAllowed(page)}
function pageRoot(){return document.querySelector('#page')}
function setActive(page){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const t=document.querySelector('#pageTitle');if(t)t.textContent=TITLE[page]||page;try{global.setSidebarOpen?.(false)}catch{}}
function modal(title,body,wide=false){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card ${wide?'restaurant-closure-wide':''}"><div class="section-head"><h2>${esc(title)}</h2><button type="button" class="secondary" data-close>إغلاق</button></div>${body}</div>`;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-close]'))m.remove()});return m}
async function askConfirm(msg){try{return await global.uiConfirm?.(msg,{title:'تأكيد'})}catch{return confirm(msg)}}
function style(){if(document.querySelector('#beta55RestaurantClosureStyle'))return;const s=document.createElement('style');s.id='beta55RestaurantClosureStyle';s.textContent=`.restaurant-closure-wide{width:min(1180px,97vw);max-height:94vh;overflow:auto}.restaurant-closure-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.restaurant-closure-grid label{display:grid;gap:5px}.restaurant-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:12px}.restaurant-kpi{padding:12px;border:1px solid rgba(128,128,128,.28);border-radius:12px}.restaurant-kpi b{display:block;font-size:21px}.restaurant-subtabs{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.restaurant-status{display:inline-block;padding:3px 8px;border-radius:999px;border:1px solid rgba(128,128,128,.35);font-size:12px}.restaurant-table-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px}.restaurant-table-card{border:1px solid rgba(128,128,128,.3);border-radius:12px;padding:12px}.restaurant-table-card.is-occupied{outline:2px solid rgba(234,179,8,.5)}.restaurant-line-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:7px;align-items:end;margin:7px 0}@media(max-width:720px){.restaurant-line-grid{grid-template-columns:1fr 1fr}.restaurant-line-grid>*:first-child{grid-column:1/-1}.restaurant-closure-wide{width:98vw}}`;document.head.appendChild(s)}

function ensureNavButton(page,label,icon,afterPage){const nav=document.querySelector('#nav');if(!nav)return null;let b=nav.querySelector(`button[data-page="${page}"]`);if(!b){b=document.createElement('button');b.type='button';b.dataset.page=page;b.textContent=`${icon} ${label}`;const after=nav.querySelector(`button[data-page="${afterPage}"]`);if(after)after.insertAdjacentElement('afterend',b);else nav.insertBefore(b,document.querySelector('#logoutMenuBtn'));}return b}
function mountNav(){if(!isRestaurant())return;style();ensureNavButton('tables','الصالات والترابيزات','🪑','kitchen');ensureNavButton('foodOperations','الإنتاج والهالك','🏭','inventory');ensureNavButton('foodRecipes','الوصفات وFood Cost','🍲','inventory');ensureNavButton('foodIngredients','الخامات','🧪','inventory');for(const p of PAGES){const b=document.querySelector(`#nav button[data-page="${p}"]`);if(b)b.classList.toggle('hidden',!canPage(p))}}
async function openPage(page){if(!canPage(page))return toast('القسم غير مفعّل أو ليس لديك صلاحية لفتحه');setActive(page);const root=pageRoot();if(root)root.innerHTML='<div class="panel"><div class="empty">جاري التحميل...</div></div>';try{await ({foodIngredients:renderIngredients,foodRecipes:renderRecipes,foodOperations:renderFoodOperations,suppliers:renderSuppliers,purchasing:renderPurchasing,stockCount:renderStockCount,transfers:renderTransfers,tables:renderTables}[page])()}catch(e){if(root)root.innerHTML=`<div class="panel"><div class="empty">${esc(e?.message||String(e))}</div></div>`;toast(e?.message||String(e))}}

function unitOptions(units,selected=''){return (units||[]).map(u=>`<option value="${esc(u.code)}" ${String(u.code)===String(selected)?'selected':''}>${esc(u.name_ar||u.code)} (${esc(u.code)})</option>`).join('')}
async function foodBaseData(){const b=branch();const [ingredients,stock,units]=await Promise.all([rest('ingredients','select=*&order=active.desc,name'),rest('ingredient_stock',`select=*&branch_id=eq.${b}`).catch(()=>[]),rest('inventory_units','select=*&active=eq.true&order=sort_order,code')]);return{ingredients,stock,units}}
function stockMap(rows){return new Map((rows||[]).map(x=>[String(x.ingredient_id),x]))}

async function renderIngredients(){const root=pageRoot(),d=await foodBaseData(),sm=stockMap(d.stock);root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🧪 الخامات — الفرع الحالي</h2><p class="muted">رصيد مستقل لكل فرع + وحدات شراء وتحويلات + متوسط تكلفة.</p></div><button class="primary" data-new>+ خامة</button></div><div class="table-wrap"><table><thead><tr><th>الخامة</th><th>الوحدة</th><th>الرصيد</th><th>متوسط التكلفة</th><th>حد أدنى</th><th>إجراءات</th></tr></thead><tbody>${d.ingredients.map(i=>{const s=sm.get(String(i.id))||{};return `<tr><td><b>${esc(i.name)}</b><small style="display:block">${esc(i.sku||i.barcode||'')}</small></td><td>${esc(i.base_unit_code||i.unit||'-')}</td><td>${fmt(s.quantity)}</td><td>${money(s.average_unit_cost||i.cost_per_unit)}</td><td>${fmt(i.minimum_quantity)}</td><td><button class="secondary" data-edit="${i.id}">✏️</button> <button class="secondary" data-adjust="${i.id}">📦 تعديل رصيد</button> <button class="secondary" data-conv="${i.id}">🔁 وحدة</button></td></tr>`}).join('')||'<tr><td colspan="6">لا توجد خامات</td></tr>'}</tbody></table></div></div>`;
 const reload=()=>renderIngredients();root.querySelector('[data-new]').onclick=()=>ingredientForm(d,null,reload);root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>ingredientForm(d,d.ingredients.find(x=>String(x.id)===b.dataset.edit),reload));root.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>ingredientAdjust(d,d.ingredients.find(x=>String(x.id)===b.dataset.adjust),reload));root.querySelectorAll('[data-conv]').forEach(b=>b.onclick=()=>ingredientConversion(d,d.ingredients.find(x=>String(x.id)===b.dataset.conv),reload));}
function ingredientForm(d,i,done){const m=modal(i?'تعديل خامة':'خامة جديدة',`<div class="restaurant-closure-grid"><label>الاسم<input data-name value="${esc(i?.name||'')}"></label><label>وحدة التخزين<select data-base>${unitOptions(d.units,i?.base_unit_code||i?.unit||'g')}</select></label><label>وحدة الشراء<select data-purchase>${unitOptions(d.units,i?.purchase_unit_code||i?.base_unit_code||i?.unit||'kg')}</select></label><label>SKU<input data-sku value="${esc(i?.sku||'')}"></label><label>Barcode<input data-barcode value="${esc(i?.barcode||'')}"></label><label>تكلفة الوحدة الأساسية<input data-cost type="number" min="0" step="0.000001" value="${Number(i?.cost_per_unit||0)}"></label><label>حد أدنى<input data-min type="number" min="0" step="0.001" value="${Number(i?.minimum_quantity||0)}"></label><label>Yield %<input data-yield type="number" min="0.01" max="100" step="0.01" value="${Number(i?.usable_yield_percent||100)}"></label><label>صلاحية بالدقائق<input data-shelf type="number" min="0" value="${i?.shelf_life_minutes??''}"></label></div><label class="inline-check"><input data-track type="checkbox" ${i?.track_inventory===false?'':'checked'}> متابعة المخزون</label><label class="inline-check"><input data-active type="checkbox" ${i?.active===false?'':'checked'}> فعالة</label><div class="modal-actions"><button class="primary" data-save>حفظ</button></div>`,true);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_ingredient_save_action_v2',{p_ingredient_id:i?.id||null,p_name:m.querySelector('[data-name]').value.trim(),p_base_unit_code:m.querySelector('[data-base]').value,p_purchase_unit_code:m.querySelector('[data-purchase]').value,p_sku:m.querySelector('[data-sku]').value.trim()||null,p_barcode:m.querySelector('[data-barcode]').value.trim()||null,p_cost_per_base_unit:Number(m.querySelector('[data-cost]').value||0),p_minimum_quantity:Number(m.querySelector('[data-min]').value||0),p_track_inventory:m.querySelector('[data-track]').checked,p_usable_yield_percent:Number(m.querySelector('[data-yield]').value||100),p_shelf_life_minutes:m.querySelector('[data-shelf]').value===''?null:Number(m.querySelector('[data-shelf]').value),p_active:m.querySelector('[data-active]').checked});m.remove();toast('تم حفظ الخامة');done()}catch(e){toast(e.message)}}}
function ingredientAdjust(d,i,done){const s=stockMap(d.stock).get(String(i.id))||{};const m=modal('تعديل رصيد خامة',`<p>الرصيد الحالي: <b>${fmt(s.quantity)} ${esc(i.base_unit_code||i.unit||'')}</b></p><div class="restaurant-closure-grid"><label>التغيير (+ إضافة / - خصم)<input data-delta type="number" step="0.001" value="0"></label><label>تكلفة الوحدة الأساسية عند الإضافة<input data-cost type="number" min="0" step="0.000001" value="${Number(s.average_unit_cost||i.cost_per_unit||0)}"></label><label>السبب<input data-reason value="تعديل يدوي"></label></div><div class="modal-actions"><button class="primary" data-save>ترحيل</button></div>`);m.querySelector('[data-save]').onclick=async()=>{const delta=Number(m.querySelector('[data-delta]').value||0);if(!delta)return toast('اكتب كمية صحيحة');try{await rpc('food_ingredient_stock_adjust_action_v2',{p_branch_id:branch(),p_ingredient_id:i.id,p_quantity_delta:delta,p_unit_cost:delta>0?Number(m.querySelector('[data-cost]').value||0):0,p_reason:m.querySelector('[data-reason]').value.trim()||null,p_client_tx_id:tx()});m.remove();toast('تم تعديل الرصيد');done()}catch(e){toast(e.message)}}}
function ingredientConversion(d,i,done){const base=i.base_unit_code||i.unit;const m=modal('تحويل وحدة خامة',`<p>وحدة التخزين الأساسية: <b>${esc(base)}</b></p><div class="restaurant-closure-grid"><label>من وحدة<select data-from>${unitOptions(d.units,i.purchase_unit_code||base)}</select></label><label>إلى وحدة<select data-to>${unitOptions(d.units,base)}</select></label><label>المعامل<input data-factor type="number" min="0.000001" step="0.000001" value="1"></label></div><div class="modal-actions"><button class="primary" data-save>حفظ التحويل</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_ingredient_conversion_save_action_v2',{p_ingredient_id:i.id,p_from_unit_code:m.querySelector('[data-from]').value,p_to_unit_code:m.querySelector('[data-to]').value,p_factor:Number(m.querySelector('[data-factor]').value||0),p_active:true});m.remove();toast('تم حفظ التحويل');done()}catch(e){toast(e.message)}}}

async function recipeData(){const [base,products,variants,headers,versions,costs]=await Promise.all([foodBaseData(),rest('products','select=id,name,active&active=eq.true&order=name'),rest('product_variants','select=id,product_id,name,active&active=eq.true&order=product_id,id').catch(()=>[]),rest('food_recipe_headers','select=*&order=id'),rest('food_recipe_versions','select=*&order=recipe_id,version_no.desc'),rest('food_recipe_branch_cost_v1',`select=*&branch_id=eq.${branch()}`).catch(()=>[])]);return{...base,products,variants,headers,versions,costs}}
async function renderRecipes(){const root=pageRoot(),d=await recipeData(),hm=new Map(d.headers.map(x=>[String(x.id),x])),pm=new Map(d.products.map(x=>[String(x.id),x])),vm=new Map(d.variants.map(x=>[String(x.id),x]));root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🍲 الوصفات وFood Cost</h2><p class="muted">كل تعديل ينشئ Version جديدة. التفعيل يحفظ تاريخ الوصفات.</p></div><button class="primary" data-new>+ Recipe</button></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>Version</th><th>الحالة</th><th>التكلفة</th><th>إجراء</th></tr></thead><tbody>${d.versions.filter(v=>hm.get(String(v.recipe_id))?.recipe_kind==='sale').map(v=>{const h=hm.get(String(v.recipe_id)),p=pm.get(String(h.product_id)),vr=h.variant_id?vm.get(String(h.variant_id)):null,c=d.costs.find(x=>String(x.recipe_version_id)===String(v.id));return `<tr><td>${esc(p?.name||h.name||h.product_id)}${vr?`<small style="display:block">${esc(vr.name)}</small>`:''}</td><td>V${v.version_no}</td><td><span class="restaurant-status">${esc(v.status)}</span></td><td>${c?money(c.recipe_cost):'-'}</td><td>${v.status==='draft'?`<button class="primary" data-activate="${v.id}">تفعيل</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد وصفات</td></tr>'}</tbody></table></div></div>`;root.querySelector('[data-new]').onclick=()=>recipeForm(d,()=>renderRecipes());root.querySelectorAll('[data-activate]').forEach(b=>b.onclick=async()=>{if(!await askConfirm('تفعيل نسخة الوصفة؟'))return;try{await rpc('food_recipe_activate_version_action_v2',{p_recipe_version_id:Number(b.dataset.activate)});toast('تم تفعيل الوصفة');renderRecipes()}catch(e){toast(e.message)}})}
function recipeForm(d,done){const ingredientOpts='<option value="">اختر خامة</option>'+d.ingredients.filter(x=>x.active!==false).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');const line=()=>`<div class="restaurant-line-grid" data-line><select data-ing>${ingredientOpts}</select><input data-qty type="number" min="0" step="0.001" placeholder="الكمية"><select data-unit>${unitOptions(d.units,'g')}</select><input data-note placeholder="ملاحظة"><button type="button" class="danger" data-del>×</button></div>`;const m=modal('Recipe جديدة',`<div class="restaurant-closure-grid"><label>الصنف<select data-product><option value="">اختر الصنف</option>${d.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Variant اختياري<select data-variant><option value="">بدون Variant</option></select></label><label>اسم الوصفة<input data-name></label><label>ناتج الوصفة<input data-output type="number" min="0.001" step="0.001" value="1"></label><label>وحدة الناتج<select data-out-unit>${unitOptions(d.units,'piece')}</select></label></div><div class="food-section"><div class="section-head"><h3>المكونات</h3><button type="button" class="secondary" data-add-line>+ سطر</button></div><div data-lines>${line()}${line()}</div></div><div class="modal-actions"><button class="primary" data-save>حفظ Draft</button></div>`,true);const prod=m.querySelector('[data-product]'),variant=m.querySelector('[data-variant]');const syncVar=()=>{const pid=prod.value;variant.innerHTML='<option value="">بدون Variant</option>'+d.variants.filter(v=>String(v.product_id)===String(pid)).map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')};prod.onchange=syncVar;m.querySelector('[data-add-line]').onclick=()=>m.querySelector('[data-lines]').insertAdjacentHTML('beforeend',line());m.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b)b.closest('[data-line]').remove()});m.querySelector('[data-save]').onclick=async()=>{const lines=[...m.querySelectorAll('[data-line]')].map((r,idx)=>({ingredient_id:Number(r.querySelector('[data-ing]').value||0),quantity:Number(r.querySelector('[data-qty]').value||0),unit_code:r.querySelector('[data-unit]').value,sort_order:idx,notes:r.querySelector('[data-note]').value.trim()||null})).filter(x=>x.ingredient_id&&x.quantity>0);if(!prod.value||!lines.length)return toast('اختر الصنف وأضف مكونًا واحدًا على الأقل');try{await rpc('food_recipe_save_draft_action_v2',{p_product_id:Number(prod.value),p_variant_id:Number(variant.value)||null,p_name:m.querySelector('[data-name]').value.trim()||null,p_output_quantity:Number(m.querySelector('[data-output]').value||1),p_output_unit_code:m.querySelector('[data-out-unit]').value,p_lines:lines,p_modifier_impacts:[],p_removal_mappings:[],p_notes:null});m.remove();toast('تم حفظ Draft الوصفة');done()}catch(e){toast(e.message)}}}

async function renderFoodOperations(){const root=pageRoot();root.innerHTML=`<div class="panel"><div class="restaurant-subtabs"><button class="primary" data-tab="production">🏭 الإنتاج</button><button class="secondary" data-tab="waste">🗑️ الهالك</button><button class="secondary" data-tab="costing">💰 Food Cost</button></div><div data-op-body></div></div>`;let tab='production';const draw=async()=>{root.querySelectorAll('[data-tab]').forEach(b=>b.className=b.dataset.tab===tab?'primary':'secondary');const box=root.querySelector('[data-op-body]');box.innerHTML='<div class="empty">جاري التحميل...</div>';if(tab==='production')await drawProduction(box);else if(tab==='waste')await drawWaste(box);else await drawCosting(box)};root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;draw().catch(e=>toast(e.message))});await draw()}
async function drawProduction(box){const [base,prep,batches,headers,versions,cons]=await Promise.all([foodBaseData(),rest('food_prep_items','select=*&order=active.desc,name'),rest('food_production_batches',`select=*&branch_id=eq.${branch()}&order=created_at.desc&limit=100`),rest('food_recipe_headers','select=*&recipe_kind=eq.prep'),rest('food_recipe_versions','select=*&order=recipe_id,version_no.desc'),rest('food_production_consumptions','select=*').catch(()=>[])]);const hm=new Map(headers.map(h=>[String(h.prep_item_id),h]));box.innerHTML=`<div class="section-head"><div><h3>Prep & Production</h3><p class="muted">تحضير نصف مصنع → Batch → استهلاك فعلي → Yield.</p></div><div><button class="secondary" data-new-prep>+ Prep</button> <button class="primary" data-start>+ Batch</button></div></div><div class="table-wrap"><table><thead><tr><th>Prep</th><th>الوحدة</th><th>Recipe</th><th>إجراء</th></tr></thead><tbody>${prep.map(p=>{const h=hm.get(String(p.id)),vs=h?versions.filter(v=>String(v.recipe_id)===String(h.id)):[];return `<tr><td>${esc(p.name)}</td><td>${esc(p.base_unit_code)}</td><td>${vs.map(v=>`V${v.version_no} ${esc(v.status)} ${v.status==='draft'?`<button class="primary" data-activate-prep="${v.id}">تفعيل</button>`:''}`).join('<br>')||'-'}</td><td><button class="secondary" data-prep-recipe="${p.id}">Recipe</button></td></tr>`}).join('')||'<tr><td colspan="4">لا توجد تحضيرات</td></tr>'}</tbody></table></div><h3>الدفعات</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Prep</th><th>المخطط</th><th>الفعلي</th><th>الحالة</th><th></th></tr></thead><tbody>${batches.map(b=>`<tr><td>${esc(b.batch_number||b.id)}</td><td>${esc(prep.find(p=>String(p.id)===String(b.prep_item_id))?.name||b.prep_item_id)}</td><td>${fmt(b.planned_output_quantity)}</td><td>${b.actual_output_quantity==null?'-':fmt(b.actual_output_quantity)}</td><td>${esc(b.status)}</td><td>${b.status==='in_progress'?`<button class="primary" data-complete="${b.id}">إكمال</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">لا توجد دفعات</td></tr>'}</tbody></table></div>`;box.querySelector('[data-new-prep]').onclick=()=>prepForm(base,()=>renderFoodOperations());box.querySelectorAll('[data-prep-recipe]').forEach(b=>b.onclick=()=>prepRecipeForm(base,prep.find(x=>String(x.id)===b.dataset.prepRecipe),()=>renderFoodOperations()));box.querySelectorAll('[data-activate-prep]').forEach(b=>b.onclick=async()=>{try{await rpc('food_recipe_activate_version_action_v2',{p_recipe_version_id:Number(b.dataset.activatePrep)});toast('تم تفعيل Recipe التحضير');renderFoodOperations()}catch(e){toast(e.message)}});box.querySelector('[data-start]').onclick=()=>startBatchForm(prep,()=>renderFoodOperations());box.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>completeBatchForm(Number(b.dataset.complete),cons.filter(x=>String(x.production_batch_id)===String(b.dataset.complete)),base.ingredients,()=>renderFoodOperations()))}
function prepForm(d,done){const m=modal('Prep Item جديد',`<div class="restaurant-closure-grid"><label>الاسم<input data-name></label><label>وحدة الناتج<select data-unit>${unitOptions(d.units,'g')}</select></label><label>Batch افتراضي<input data-batch type="number" min="0.001" step="0.001" value="1"></label><label>خامة ناتج موجودة<select data-output><option value="">إنشاء خامة ناتج تلقائيًا</option>${d.ingredients.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></label><label>صلاحية بالدقائق<input data-shelf type="number" min="0"></label><label>ملاحظات<input data-notes></label></div><div class="modal-actions"><button class="primary" data-save>حفظ</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_prep_item_save_action_v2',{p_prep_item_id:null,p_name:m.querySelector('[data-name]').value.trim(),p_output_ingredient_id:Number(m.querySelector('[data-output]').value)||null,p_base_unit_code:m.querySelector('[data-unit]').value,p_default_batch_quantity:Number(m.querySelector('[data-batch]').value||1),p_shelf_life_minutes:m.querySelector('[data-shelf]').value===''?null:Number(m.querySelector('[data-shelf]').value),p_notes:m.querySelector('[data-notes]').value.trim()||null,p_active:true});m.remove();toast('تم حفظ التحضير');done()}catch(e){toast(e.message)}}}
function prepRecipeForm(d,prep,done){const ingOpts='<option value="">اختر خامة</option>'+d.ingredients.filter(x=>x.active!==false).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');const row=()=>`<div class="restaurant-line-grid" data-line><select data-ing>${ingOpts}</select><input data-qty type="number" min="0" step="0.001" placeholder="الكمية"><select data-unit>${unitOptions(d.units,'g')}</select><input data-note placeholder="ملاحظة"><button type="button" class="danger" data-del>×</button></div>`;const m=modal(`Recipe تحضير — ${prep?.name||''}`,`<div class="restaurant-closure-grid"><label>ناتج التحضير<input data-output type="number" min="0.001" step="0.001" value="${Number(prep?.default_batch_quantity||1)}"></label><label>الوحدة<input data-unit-out value="${esc(prep?.base_unit_code||'g')}" disabled></label></div><div data-lines>${row()}${row()}</div><button class="secondary" data-add>+ سطر</button><div class="modal-actions"><button class="primary" data-save>حفظ Draft</button></div>`,true);m.querySelector('[data-add]').onclick=()=>m.querySelector('[data-lines]').insertAdjacentHTML('beforeend',row());m.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b)b.closest('[data-line]').remove()});m.querySelector('[data-save]').onclick=async()=>{const lines=[...m.querySelectorAll('[data-line]')].map((r,i)=>({ingredient_id:Number(r.querySelector('[data-ing]').value||0),quantity:Number(r.querySelector('[data-qty]').value||0),unit_code:r.querySelector('[data-unit]').value,sort_order:i,notes:r.querySelector('[data-note]').value.trim()||null})).filter(x=>x.ingredient_id&&x.quantity>0);if(!lines.length)return toast('أضف خامة واحدة على الأقل');try{await rpc('food_prep_recipe_save_draft_action_v2',{p_prep_item_id:prep.id,p_output_quantity:Number(m.querySelector('[data-output]').value||1),p_output_unit_code:prep.base_unit_code,p_lines:lines,p_notes:null});m.remove();toast('تم حفظ Recipe التحضير');done()}catch(e){toast(e.message)}}}
function startBatchForm(prep,done){const m=modal('بدء Batch',`<div class="restaurant-closure-grid"><label>Prep<select data-prep><option value="">اختر</option>${prep.filter(x=>x.active!==false).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>الكمية المخططة<input data-qty type="number" min="0.001" step="0.001" value="1"></label><label>رقم Batch<input data-no></label><label>ملاحظات<input data-notes></label></div><div class="modal-actions"><button class="primary" data-save>بدء</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_production_batch_start_action_v2',{p_branch_id:branch(),p_prep_item_id:Number(m.querySelector('[data-prep]').value),p_planned_output_quantity:Number(m.querySelector('[data-qty]').value||0),p_batch_number:m.querySelector('[data-no]').value.trim()||null,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_client_tx_id:tx()});m.remove();toast('تم بدء Batch');done()}catch(e){toast(e.message)}}}
function completeBatchForm(batchId,cons,ingredients,done){const im=new Map(ingredients.map(i=>[String(i.id),i]));const m=modal(`إكمال Batch #${batchId}`,`<div class="restaurant-closure-grid"><label>الناتج الفعلي<input data-output type="number" min="0.001" step="0.001" value="1"></label></div><h3>الاستهلاك الفعلي بالوحدة الأساسية</h3>${cons.map(c=>`<label style="display:grid;grid-template-columns:1fr 160px;gap:10px;margin:6px 0"><span>${esc(im.get(String(c.ingredient_id))?.name||c.ingredient_id)} <small>المخطط ${fmt(c.planned_base_quantity)}</small></span><input data-cons="${c.ingredient_id}" type="number" min="0" step="0.001" value="${Number(c.planned_base_quantity||0)}"></label>`).join('')}<div class="modal-actions"><button class="primary" data-save>إكمال وترحيل</button></div>`,true);m.querySelector('[data-save]').onclick=async()=>{const rows=[...m.querySelectorAll('[data-cons]')].map(x=>({ingredient_id:Number(x.dataset.cons),actual_base_quantity:Number(x.value||0)}));try{await rpc('food_production_batch_complete_action_v2',{p_production_batch_id:batchId,p_actual_output_quantity:Number(m.querySelector('[data-output]').value||0),p_consumptions:rows,p_client_tx_id:tx(),p_notes:null});m.remove();toast('تم إكمال Batch');done()}catch(e){toast(e.message)}}}
async function drawWaste(box){const [base,reasons,events]=await Promise.all([foodBaseData(),rest('food_waste_reasons','select=*&active=eq.true&order=sort_order'),rest('food_waste_events',`select=*&branch_id=eq.${branch()}&order=occurred_at.desc&limit=100`)]);const im=new Map(base.ingredients.map(i=>[String(i.id),i])),rm=new Map(reasons.map(r=>[String(r.code),r]));box.innerHTML=`<div class="section-head"><div><h3>🗑️ الهالك</h3><p class="muted">الترحيل يخصم من مخزون الخامة فورًا ويحفظ التكلفة.</p></div><button class="danger" data-new>+ تسجيل هالك</button></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>الخامة</th><th>السبب</th><th>الكمية</th><th>التكلفة</th></tr></thead><tbody>${events.map(w=>`<tr><td>${new Date(w.occurred_at).toLocaleString('ar-EG')}</td><td>${esc(im.get(String(w.ingredient_id))?.name||w.ingredient_id)}</td><td>${esc(rm.get(String(w.reason_code))?.name_ar||w.reason_code)}</td><td>${fmt(w.quantity)} ${esc(w.unit_code)}</td><td>${money(w.waste_cost)}</td></tr>`).join('')||'<tr><td colspan="5">لا يوجد هالك</td></tr>'}</tbody></table></div>`;box.querySelector('[data-new]').onclick=()=>wasteForm(base,reasons,()=>renderFoodOperations())}
function wasteForm(d,reasons,done){const m=modal('تسجيل هالك',`<div class="restaurant-closure-grid"><label>الخامة<select data-ing><option value="">اختر</option>${d.ingredients.filter(x=>x.active!==false).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></label><label>السبب<select data-reason>${reasons.map(r=>`<option value="${esc(r.code)}">${esc(r.name_ar||r.code)}</option>`).join('')}</select></label><label>الكمية<input data-qty type="number" min="0.001" step="0.001"></label><label>الوحدة<select data-unit>${unitOptions(d.units,'g')}</select></label><label>ملاحظات<input data-notes></label></div><div class="modal-actions"><button class="danger" data-save>ترحيل الهالك</button></div>`);const ing=m.querySelector('[data-ing]');ing.onchange=()=>{const i=d.ingredients.find(x=>String(x.id)===ing.value);if(i)m.querySelector('[data-unit]').value=i.base_unit_code||i.unit||m.querySelector('[data-unit]').value};m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_waste_post_action_v2',{p_branch_id:branch(),p_ingredient_id:Number(ing.value),p_prep_item_id:null,p_shift_id:null,p_reason_code:m.querySelector('[data-reason]').value,p_quantity:Number(m.querySelector('[data-qty]').value||0),p_unit_code:m.querySelector('[data-unit]').value,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_client_tx_id:tx()});m.remove();toast('تم ترحيل الهالك');done()}catch(e){toast(e.message)}}}
async function drawCosting(box){const [costing,theory]=await Promise.all([rest('food_menu_costing_v1',`select=*&branch_id=eq.${branch()}&order=food_cost_percent.desc`).catch(()=>[]),rest('food_theoretical_consumption_net_v1',`select=*&branch_id=eq.${branch()}&order=business_date.desc`).catch(()=>[])]);box.innerHTML=`<h3>Food Cost</h3><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>البيع</th><th>Food Cost</th><th>%</th><th>Gross Margin</th></tr></thead><tbody>${costing.map(c=>`<tr><td>${esc(c.product_name)}${c.variant_name?` — ${esc(c.variant_name)}`:''}</td><td>${money(c.selling_price)}</td><td>${money(c.recipe_cost)}</td><td>${c.food_cost_percent==null?'-':Number(c.food_cost_percent).toFixed(2)+'%'}</td><td>${money(c.gross_margin)}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد وصفات فعالة محسوبة بعد</td></tr>'}</tbody></table></div><h3>الاستهلاك النظري Net of Returns</h3><div class="table-wrap"><table><thead><tr><th>اليوم</th><th>الخامة</th><th>الكمية النظرية</th><th>التكلفة</th></tr></thead><tbody>${theory.slice(0,150).map(x=>`<tr><td>${esc(x.business_date)}</td><td>${esc(x.ingredient_id)}</td><td>${fmt(x.theoretical_base_quantity)}</td><td>${money(x.theoretical_cost)}</td></tr>`).join('')||'<tr><td colspan="4">لا توجد حركة نظرية بعد</td></tr>'}</tbody></table></div>`}

async function renderSuppliers(){const root=pageRoot(),rows=await rest('suppliers','select=*&order=active.desc,name');root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🚚 الموردين</h2><p class="muted">موردي الخامات وبيانات التواصل.</p></div><button class="primary" data-new>+ مورد</button></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>Email</th><th>الرقم الضريبي</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.phone||'-')}</td><td>${esc(s.email||'-')}</td><td>${esc(s.tax_no||'-')}</td><td>${s.active===false?'موقوف':'فعال'}</td><td><button class="secondary" data-edit="${s.id}">تعديل</button></td></tr>`).join('')||'<tr><td colspan="6">لا يوجد موردون</td></tr>'}</tbody></table></div></div>`;root.querySelector('[data-new]').onclick=()=>supplierForm(null,()=>renderSuppliers());root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>supplierForm(rows.find(x=>String(x.id)===b.dataset.edit),()=>renderSuppliers()))}
function supplierForm(s,done){const m=modal(s?'تعديل مورد':'مورد جديد',`<div class="restaurant-closure-grid"><label>الاسم<input data-name value="${esc(s?.name||'')}"></label><label>الهاتف<input data-phone value="${esc(s?.phone||'')}"></label><label>Email<input data-email value="${esc(s?.email||'')}"></label><label>رقم ضريبي<input data-tax value="${esc(s?.tax_no||'')}"></label><label>العنوان<input data-address value="${esc(s?.address||'')}"></label><label>ملاحظات<input data-notes value="${esc(s?.notes||'')}"></label></div><label class="inline-check"><input data-active type="checkbox" ${s?.active===false?'':'checked'}> فعال</label><div class="modal-actions"><button class="primary" data-save>حفظ</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('food_supplier_save_v1',{p_supplier_id:s?.id||null,p_name:m.querySelector('[data-name]').value.trim(),p_phone:m.querySelector('[data-phone]').value.trim()||null,p_email:m.querySelector('[data-email]').value.trim()||null,p_tax_no:m.querySelector('[data-tax]').value.trim()||null,p_address:m.querySelector('[data-address]').value.trim()||null,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_active:m.querySelector('[data-active]').checked});m.remove();toast('تم حفظ المورد');done()}catch(e){toast(e.message)}}}

async function purchasingData(){const b=branch();const [suppliers,ingredients,units,purchases,items,receipts]=await Promise.all([rest('suppliers','select=*&active=is.true&order=name'),rest('ingredients','select=*&active=is.true&order=name'),rest('inventory_units','select=*&active=eq.true&order=sort_order,code'),rest('purchases',`select=*&branch_id=eq.${b}&order=created_at.desc&limit=100`),rest('purchase_items','select=*'),rest('food_purchase_receipts',`select=*&branch_id=eq.${b}&order=received_at.desc&limit=100`).catch(()=>[])]);return{suppliers,ingredients,units,purchases,items,receipts}}
async function renderPurchasing(){const root=pageRoot(),d=await purchasingData(),sm=new Map(d.suppliers.map(s=>[String(s.id),s]));root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>📥 مشتريات الخامات والاستلام</h2><p class="muted">Draft → Approved → Partial/Received. الاستلام هو الذي يزيد مخزون الخامة.</p></div><div><button class="secondary" data-return>↩️ مرتجع مورد</button> <button class="primary" data-new>+ أمر شراء</button></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>المورد</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th><th>إجراءات</th></tr></thead><tbody>${d.purchases.map(p=>`<tr><td>${p.id}</td><td>${esc(sm.get(String(p.supplier_id))?.name||'-')}</td><td>${money(p.total)}</td><td><span class="restaurant-status">${esc(p.status||'draft')}</span></td><td>${new Date(p.created_at).toLocaleString('ar-EG')}</td><td>${p.status==='draft'?`<button class="primary" data-approve="${p.id}">اعتماد</button> <button class="danger" data-cancel="${p.id}">إلغاء</button>`:''}${['approved','partially_received'].includes(p.status)?`<button class="primary" data-receive="${p.id}">استلام</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">لا توجد أوامر شراء</td></tr>'}</tbody></table></div></div>`;root.querySelector('[data-new]').onclick=()=>purchaseForm(d,()=>renderPurchasing());root.querySelector('[data-return]').onclick=()=>supplierReturnForm(d,()=>renderPurchasing());root.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{try{await rpc('food_purchase_order_approve_v1',{p_purchase_id:Number(b.dataset.approve)});toast('تم الاعتماد');renderPurchasing()}catch(e){toast(e.message)}});root.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!await askConfirm('إلغاء أمر الشراء؟'))return;try{await rpc('food_purchase_order_cancel_v1',{p_purchase_id:Number(b.dataset.cancel),p_reason:'إلغاء من POS'});toast('تم الإلغاء');renderPurchasing()}catch(e){toast(e.message)}});root.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>receiveForm(d,Number(b.dataset.receive),()=>renderPurchasing()))}
function purchaseForm(d,done){const ingOpts='<option value="">اختر خامة</option>'+d.ingredients.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');const row=()=>`<div class="restaurant-line-grid" data-line><select data-ing>${ingOpts}</select><input data-qty type="number" min="0" step="0.001" placeholder="الكمية"><select data-unit>${unitOptions(d.units,'kg')}</select><input data-cost type="number" min="0" step="0.01" placeholder="تكلفة الوحدة"><button type="button" class="danger" data-del>×</button></div>`;const m=modal('أمر شراء خامات',`<div class="restaurant-closure-grid"><label>المورد<select data-supplier><option value="">اختر</option>${d.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>رقم فاتورة/مرجع<input data-invoice></label><label>ملاحظات<input data-notes></label></div><div class="section-head"><h3>الخامات</h3><button class="secondary" data-add>+ سطر</button></div><div data-lines>${row()}${row()}</div><div class="modal-actions"><button class="primary" data-save>حفظ Draft</button></div>`,true);m.querySelector('[data-add]').onclick=()=>m.querySelector('[data-lines]').insertAdjacentHTML('beforeend',row());m.addEventListener('change',e=>{const s=e.target.closest('[data-ing]');if(!s)return;const i=d.ingredients.find(x=>String(x.id)===s.value),r=s.closest('[data-line]');if(i&&r)r.querySelector('[data-unit]').value=i.purchase_unit_code||i.base_unit_code||i.unit||r.querySelector('[data-unit]').value});m.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b)b.closest('[data-line]').remove()});m.querySelector('[data-save]').onclick=async()=>{const items=[...m.querySelectorAll('[data-line]')].map(r=>({ingredient_id:Number(r.querySelector('[data-ing]').value||0),quantity:Number(r.querySelector('[data-qty]').value||0),unit_code:r.querySelector('[data-unit]').value,unit_cost:Number(r.querySelector('[data-cost]').value||0)})).filter(x=>x.ingredient_id&&x.quantity>0);if(!m.querySelector('[data-supplier]').value||!items.length)return toast('اختر المورد وأضف خامة');try{await rpc('food_purchase_order_create_v1',{p_branch_id:branch(),p_supplier_id:Number(m.querySelector('[data-supplier]').value),p_invoice_number:m.querySelector('[data-invoice]').value.trim()||null,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_items:items,p_client_tx_id:tx()});m.remove();toast('تم حفظ أمر الشراء');done()}catch(e){toast(e.message)}}}
function receiveForm(d,purchaseId,done){const rows=d.items.filter(x=>String(x.purchase_id)===String(purchaseId)&&Number(x.received_quantity||0)<Number(x.quantity||0));const im=new Map(d.ingredients.map(i=>[String(i.id),i]));if(!rows.length)return toast('لا توجد كميات متبقية للاستلام');const m=modal(`استلام أمر شراء #${purchaseId}`,`<p class="muted">يمكن استلام كامل المتبقي أو جزء منه.</p>${rows.map(r=>`<label style="display:grid;grid-template-columns:1fr 170px;gap:10px;margin:8px 0"><span>${esc(im.get(String(r.ingredient_id))?.name||r.ingredient_id)} <small>المتبقي ${fmt(Number(r.quantity)-Number(r.received_quantity||0))} ${esc(r.unit_code||'')}</small></span><input data-line="${r.id}" type="number" min="0" max="${Number(r.quantity)-Number(r.received_quantity||0)}" step="0.001" value="${Number(r.quantity)-Number(r.received_quantity||0)}"></label>`).join('')}<div class="modal-actions"><button class="primary" data-save>ترحيل الاستلام</button></div>`,true);m.querySelector('[data-save]').onclick=async()=>{const items=[...m.querySelectorAll('[data-line]')].map(x=>({purchase_item_id:Number(x.dataset.line),quantity:Number(x.value||0)})).filter(x=>x.quantity>0);if(!items.length)return toast('لا توجد كمية للاستلام');try{await rpc('food_purchase_receive_v1',{p_purchase_id:purchaseId,p_items:items,p_client_tx_id:tx()});m.remove();toast('تم استلام الخامات وتحديث المخزون');done()}catch(e){toast(e.message)}}}
function supplierReturnForm(d,done){const ingOpts='<option value="">اختر خامة</option>'+d.ingredients.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');const row=()=>`<div class="restaurant-line-grid" data-line><select data-ing>${ingOpts}</select><input data-qty type="number" min="0" step="0.001" placeholder="الكمية"><select data-unit>${unitOptions(d.units,'kg')}</select><input data-note placeholder=""><button type="button" class="danger" data-del>×</button></div>`;const m=modal('مرتجع مورد خامات',`<div class="restaurant-closure-grid"><label>المورد<select data-supplier><option value="">بدون تحديد</option>${d.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>ملاحظات<input data-notes></label></div><div data-lines>${row()}</div><button class="secondary" data-add>+ سطر</button><div class="modal-actions"><button class="danger" data-save>ترحيل المرتجع</button></div>`,true);m.querySelector('[data-add]').onclick=()=>m.querySelector('[data-lines]').insertAdjacentHTML('beforeend',row());m.addEventListener('change',e=>{const s=e.target.closest('[data-ing]');if(!s)return;const i=d.ingredients.find(x=>String(x.id)===s.value),r=s.closest('[data-line]');if(i&&r)r.querySelector('[data-unit]').value=i.purchase_unit_code||i.base_unit_code||i.unit||r.querySelector('[data-unit]').value});m.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b)b.closest('[data-line]').remove()});m.querySelector('[data-save]').onclick=async()=>{const items=[...m.querySelectorAll('[data-line]')].map(r=>({ingredient_id:Number(r.querySelector('[data-ing]').value||0),quantity:Number(r.querySelector('[data-qty]').value||0),unit_code:r.querySelector('[data-unit]').value})).filter(x=>x.ingredient_id&&x.quantity>0);if(!items.length)return toast('أضف خامة للمرتجع');try{await rpc('food_supplier_return_create_v1',{p_branch_id:branch(),p_supplier_id:Number(m.querySelector('[data-supplier]').value)||null,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_items:items,p_client_tx_id:tx()});m.remove();toast('تم ترحيل مرتجع المورد');done()}catch(e){toast(e.message)}}}

async function renderStockCount(){const root=pageRoot(),d=await foodBaseData(),sm=stockMap(d.stock),rows=d.ingredients.filter(i=>i.active!==false&&i.track_inventory!==false);root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🧮 جرد الخامات</h2><p class="muted">اكتب الرصيد الفعلي بالوحدة الأساسية. الترحيل يسجل الفرق فقط.</p></div><button class="primary" data-post>ترحيل الجرد</button></div><div class="table-wrap"><table><thead><tr><th>الخامة</th><th>الوحدة</th><th>رصيد النظام</th><th>الفعلي</th><th>الفرق</th></tr></thead><tbody>${rows.map(i=>{const q=Number(sm.get(String(i.id))?.quantity||0);return `<tr><td>${esc(i.name)}</td><td>${esc(i.base_unit_code||i.unit)}</td><td data-system="${i.id}">${fmt(q)}</td><td><input data-count="${i.id}" type="number" min="0" step="0.001" value="${q}"></td><td data-diff="${i.id}">0.000</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد خامات متتبعة</td></tr>'}</tbody></table></div></div>`;root.querySelectorAll('[data-count]').forEach(inp=>inp.oninput=()=>{const i=rows.find(x=>String(x.id)===inp.dataset.count),sys=Number(sm.get(String(i.id))?.quantity||0),dif=Number(inp.value||0)-sys;root.querySelector(`[data-diff="${i.id}"]`).textContent=fmt(dif)});root.querySelector('[data-post]').onclick=async()=>{if(!await askConfirm('ترحيل جرد الخامات وتعديل الأرصدة؟'))return;const items=[...root.querySelectorAll('[data-count]')].map(x=>({ingredient_id:Number(x.dataset.count),counted_quantity:Number(x.value||0)}));try{await rpc('food_stock_count_post_v1',{p_branch_id:branch(),p_notes:'جرد من POS',p_items:items,p_client_tx_id:tx()});toast('تم ترحيل الجرد');renderStockCount()}catch(e){toast(e.message)}}}

async function renderTransfers(){const root=pageRoot(),b=branch(),[base,branches,transfers,items]=await Promise.all([foodBaseData(),rest('branches','select=id,name,active&active=eq.true&order=sort_order,id'),rest('stock_transfers',`select=*&or=(from_branch_id.eq.${b},to_branch_id.eq.${b})&order=created_at.desc&limit=100`),rest('stock_transfer_items','select=*')]);const bm=new Map(branches.map(x=>[String(x.id),x]));root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🔄 تحويلات الخامات</h2><p class="muted">الإرسال يخصم من المصدر فورًا؛ الاستلام فقط يضيف للمستلم.</p></div><button class="primary" data-new>+ تحويل</button></div><div class="table-wrap"><table><thead><tr><th>#</th><th>من</th><th>إلى</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody>${transfers.map(t=>`<tr><td>${t.id}</td><td>${esc(bm.get(String(t.from_branch_id))?.name||t.from_branch_id)}</td><td>${esc(bm.get(String(t.to_branch_id))?.name||t.to_branch_id)}</td><td>${esc(t.status)}</td><td>${new Date(t.created_at).toLocaleString('ar-EG')}</td><td>${t.status==='sent'&&Number(t.to_branch_id)===b?`<button class="primary" data-receive="${t.id}">استلام</button>`:''}${t.status==='sent'&&Number(t.from_branch_id)===b?`<button class="danger" data-cancel="${t.id}">إلغاء</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">لا توجد تحويلات</td></tr>'}</tbody></table></div></div>`;root.querySelector('[data-new]').onclick=()=>transferForm(base,branches,()=>renderTransfers());root.querySelectorAll('[data-receive]').forEach(x=>x.onclick=async()=>{try{await rpc('food_stock_transfer_receive_v1',{p_transfer_id:Number(x.dataset.receive)});toast('تم استلام التحويل');renderTransfers()}catch(e){toast(e.message)}});root.querySelectorAll('[data-cancel]').forEach(x=>x.onclick=async()=>{if(!await askConfirm('إلغاء التحويل وإرجاع الكميات للمصدر؟'))return;try{await rpc('food_stock_transfer_cancel_v1',{p_transfer_id:Number(x.dataset.cancel),p_reason:'إلغاء من POS'});toast('تم إلغاء التحويل');renderTransfers()}catch(e){toast(e.message)}})}
function transferForm(d,branches,done){const targets=branches.filter(x=>Number(x.id)!==branch()),im='<option value="">اختر خامة</option>'+d.ingredients.filter(i=>i.active!==false&&i.track_inventory!==false).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');const row=()=>`<div class="restaurant-line-grid" data-line><select data-ing>${im}</select><input data-qty type="number" min="0" step="0.001" placeholder="كمية بالوحدة الأساسية"><span></span><span></span><button type="button" class="danger" data-del>×</button></div>`;const m=modal('تحويل خامات',`<div class="restaurant-closure-grid"><label>الفرع المستلم<select data-target><option value="">اختر</option>${targets.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>ملاحظات<input data-notes></label></div><div data-lines>${row()}</div><button class="secondary" data-add>+ سطر</button><div class="modal-actions"><button class="primary" data-save>إرسال التحويل</button></div>`,true);m.querySelector('[data-add]').onclick=()=>m.querySelector('[data-lines]').insertAdjacentHTML('beforeend',row());m.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b)b.closest('[data-line]').remove()});m.querySelector('[data-save]').onclick=async()=>{const items=[...m.querySelectorAll('[data-line]')].map(r=>({ingredient_id:Number(r.querySelector('[data-ing]').value||0),quantity:Number(r.querySelector('[data-qty]').value||0)})).filter(x=>x.ingredient_id&&x.quantity>0);if(!m.querySelector('[data-target]').value||!items.length)return toast('اختر الفرع وأضف خامة');try{await rpc('food_stock_transfer_create_v1',{p_from_branch_id:branch(),p_to_branch_id:Number(m.querySelector('[data-target]').value),p_items:items,p_notes:m.querySelector('[data-notes]').value.trim()||null,p_client_tx_id:tx()});m.remove();toast('تم إرسال التحويل');done()}catch(e){toast(e.message)}}}

async function renderTables(){const root=pageRoot(),b=branch(),[floors,tables,sessions,links,orders]=await Promise.all([rest('restaurant_floors',`select=*&branch_id=eq.${b}&order=sort_order,id`),rest('restaurant_tables',`select=*&branch_id=eq.${b}&order=floor_id,id`),rest('restaurant_table_sessions',`select=*&branch_id=eq.${b}&order=opened_at.desc&limit=200`),rest('restaurant_table_session_orders','select=*').catch(()=>[]),rest('orders',`select=id,invoice_number,bon_number,total,status,created_at,order_type&branch_id=eq.${b}&order_type=eq.dinein&order=created_at.desc&limit=100`).catch(()=>[])]);const openByTable=new Map(sessions.filter(s=>s.status==='open').map(s=>[String(s.table_id),s])),fm=new Map(floors.map(f=>[String(f.id),f]));root.innerHTML=`<div class="panel"><div class="section-head"><div><h2>🪑 الصالات والترابيزات</h2><p class="muted">فتح جلسة، عدد ضيوف، ربط طلب صالة، ثم إغلاق الجلسة.</p></div><div><button class="secondary" data-floor>+ صالة</button> <button class="primary" data-table>+ ترابيزة</button></div></div><div class="restaurant-table-grid">${tables.map(t=>{const s=openByTable.get(String(t.id)),count=s?links.filter(x=>String(x.session_id)===String(s.id)).length:0;return `<div class="restaurant-table-card ${s?'is-occupied':''}"><small>${esc(fm.get(String(t.floor_id))?.name||'بدون صالة')}</small><h3>${esc(t.name)}</h3><div>${t.capacity} مقاعد • <span class="restaurant-status">${esc(t.status)}</span></div>${s?`<p>جلسة #${s.id} • ${s.guest_count} ضيف • ${count} طلب</p><button class="secondary" data-attach="${s.id}">ربط طلب</button> <button class="primary" data-close-session="${s.id}">إغلاق الجلسة</button>`:`<button class="primary" data-open="${t.id}" ${t.active===false?'disabled':''}>فتح جلسة</button>`} <button class="secondary" data-edit-table="${t.id}">✏️</button></div>`}).join('')||'<div class="empty">أضف صالة وترابيزات للبدء</div>'}</div></div>`;root.querySelector('[data-floor]').onclick=()=>floorForm(null,()=>renderTables());root.querySelector('[data-table]').onclick=()=>tableForm(floors,null,()=>renderTables());root.querySelectorAll('[data-edit-table]').forEach(x=>x.onclick=()=>tableForm(floors,tables.find(t=>String(t.id)===x.dataset.editTable),()=>renderTables()));root.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>openSessionForm(Number(x.dataset.open),()=>renderTables()));root.querySelectorAll('[data-close-session]').forEach(x=>x.onclick=async()=>{try{await rpc('restaurant_table_session_close_v1',{p_session_id:Number(x.dataset.closeSession),p_notes:null});toast('تم إغلاق الجلسة');renderTables()}catch(e){toast(e.message)}});root.querySelectorAll('[data-attach]').forEach(x=>x.onclick=()=>attachOrderForm(Number(x.dataset.attach),orders,links,()=>renderTables()))}
function floorForm(f,done){const m=modal(f?'تعديل صالة':'صالة جديدة',`<div class="restaurant-closure-grid"><label>الاسم<input data-name value="${esc(f?.name||'')}"></label><label>الترتيب<input data-sort type="number" value="${Number(f?.sort_order||100)}"></label></div><div class="modal-actions"><button class="primary" data-save>حفظ</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('restaurant_floor_save_v1',{p_floor_id:f?.id||null,p_branch_id:branch(),p_name:m.querySelector('[data-name]').value.trim(),p_sort_order:Number(m.querySelector('[data-sort]').value||100),p_active:true});m.remove();toast('تم حفظ الصالة');done()}catch(e){toast(e.message)}}}
function tableForm(floors,t,done){const m=modal(t?'تعديل ترابيزة':'ترابيزة جديدة',`<div class="restaurant-closure-grid"><label>الاسم<input data-name value="${esc(t?.name||'')}"></label><label>الكود<input data-code value="${esc(t?.code||'')}"></label><label>الصالة<select data-floor><option value="">بدون</option>${floors.filter(f=>f.active!==false).map(f=>`<option value="${f.id}" ${String(f.id)===String(t?.floor_id)?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label>عدد المقاعد<input data-capacity type="number" min="1" value="${Number(t?.capacity||2)}"></label></div><label class="inline-check"><input data-active type="checkbox" ${t?.active===false?'':'checked'}> فعالة</label><div class="modal-actions"><button class="primary" data-save>حفظ</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('restaurant_table_save_v1',{p_table_id:t?.id||null,p_branch_id:branch(),p_floor_id:Number(m.querySelector('[data-floor]').value)||null,p_name:m.querySelector('[data-name]').value.trim(),p_code:m.querySelector('[data-code]').value.trim()||null,p_capacity:Number(m.querySelector('[data-capacity]').value||2),p_active:m.querySelector('[data-active]').checked});m.remove();toast('تم حفظ الترابيزة');done()}catch(e){toast(e.message)}}}
function openSessionForm(tableId,done){const m=modal('فتح جلسة ترابيزة',`<div class="restaurant-closure-grid"><label>عدد الضيوف<input data-guests type="number" min="1" value="2"></label><label>ملاحظات<input data-notes></label></div><div class="modal-actions"><button class="primary" data-save>فتح الجلسة</button></div>`);m.querySelector('[data-save]').onclick=async()=>{try{await rpc('restaurant_table_session_open_v1',{p_table_id:tableId,p_guest_count:Number(m.querySelector('[data-guests]').value||1),p_notes:m.querySelector('[data-notes]').value.trim()||null,p_client_tx_id:tx()});m.remove();toast('تم فتح الجلسة');done()}catch(e){toast(e.message)}}}
function attachOrderForm(sessionId,orders,links,done){const used=new Set(links.map(x=>String(x.order_id))),available=orders.filter(o=>!used.has(String(o.id)));const m=modal('ربط طلب صالة',`<label>الطلب<select data-order><option value="">اختر طلب صالة</option>${available.map(o=>`<option value="${o.id}">${esc(o.bon_number||o.invoice_number||o.id)} — ${money(o.total)} — ${new Date(o.created_at).toLocaleString('ar-EG')}</option>`).join('')}</select></label><div class="modal-actions"><button class="primary" data-save>ربط</button></div>`);m.querySelector('[data-save]').onclick=async()=>{if(!m.querySelector('[data-order]').value)return toast('اختر الطلب');try{await rpc('restaurant_table_session_attach_order_v1',{p_session_id:sessionId,p_order_id:Number(m.querySelector('[data-order]').value)});m.remove();toast('تم ربط الطلب بالجلسة');done()}catch(e){toast(e.message)}}}

function interceptNav(){const nav=document.querySelector('#nav');if(!nav||nav.dataset.restaurantClosureWired==='1')return;nav.dataset.restaurantClosureWired='1';nav.addEventListener('click',e=>{if(!isRestaurant())return;const b=e.target.closest('button[data-page]');if(!b||!PAGES.has(b.dataset.page))return;e.preventDefault();e.stopImmediatePropagation();openPage(b.dataset.page)},true)}
function boot(){if(wired)return;wired=true;const run=()=>{if(isRestaurant()){mountNav();interceptNav()}};run();const mo=new MutationObserver(()=>{if(isRestaurant())mountNav()});mo.observe(document.body,{childList:true,subtree:true});global.__SharawlaRestaurantClosureV55=Object.freeze({version:VERSION,pages:[...PAGES],openPage,canPage})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})(window);
